<?php
require_once '../includes/security.php';start_secure_session();require_roles(['admin']);require_csrf();require '../includes/db.php';require 'audit.php';
$state=$_SESSION['family_import_preview']??null;$token=(string)($_POST['preview_token']??'');if(!$state||!hash_equals($state['token'],$token)||time()-(int)$state['created']>3600||!is_file($state['path'])){header('Location: ../auth/families/import.php?error=preview_expired');exit;}
if(!$state['ownership']){header('Location: ../auth/families/import.php?error=ownership_required');exit;}$preview=$state['preview'];$userId=(int)$_SESSION['user_id'];
$stmt=$conn->prepare("INSERT INTO import_batches(source_type,source_name,source_hash,status,validation_summary,created_by,started_at) VALUES('ip_family_workbook',?,?,'validated',?,?,NOW())");$summary=json_encode(['total'=>$preview['total'],'valid'=>$preview['valid'],'warning'=>$preview['warning'],'invalid'=>$preview['invalid'],'duplicates'=>$preview['duplicates']]);$stmt->bind_param('sssi',$state['name'],$state['hash'],$summary,$userId);
try{$stmt->execute();}catch(mysqli_sql_exception $e){header('Location: ../auth/families/import.php?error=duplicate_file');exit;}$batchId=$conn->insert_id;$imported=0;$skipped=0;
try{$conn->begin_transaction();$conn->query("UPDATE import_batches SET status='importing' WHERE id=".(int)$batchId);foreach($preview['rows'] as $row){if($row['status']==='invalid'){$skipped++;continue;}$f=$row['family'];$ref='FAM-'.date('Y').'-'.strtoupper(bin2hex(random_bytes(4)));$stmt=$conn->prepare('INSERT INTO ip_families(family_reference,affiliation_id,owning_tribe,region,province,municipality_city,barangay,house_number,sitio_street,contact_number,id_type,id_number,remarks,import_batch_id,source_reference,imported_at,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),?,?)');$stmt->bind_param('sisssssssssssisii',$ref,$row['affiliation_id'],$state['ownership'],$f['region'],$f['province'],$f['municipality_city'],$f['barangay'],$f['house_number'],$f['sitio_street'],$f['contact_number'],$f['id_type'],$f['id_number'],$f['remarks'],$batchId,$row['source_reference'],$userId,$userId);$stmt->execute();$fid=$conn->insert_id;foreach(['head','spouse'] as $role){$p=$row[$role];if(!$p)continue;$stmt=$conn->prepare('INSERT INTO ip_family_members(family_id,member_role,last_name,first_name,middle_name,suffix,sex,birthdate) VALUES(?,?,?,?,?,?,?,?)');$stmt->bind_param('isssssss',$fid,$role,$p['last_name'],$p['first_name'],$p['middle_name'],$p['suffix'],$p['sex'],$p['birthdate']);$stmt->execute();}$imported++;}$final=json_encode(['imported'=>$imported,'skipped'=>$skipped,'total'=>$preview['total']]);$stmt=$conn->prepare("UPDATE import_batches SET status='completed',validation_summary=?,completed_at=NOW() WHERE id=?");$stmt->bind_param('si',$final,$batchId);$stmt->execute();$conn->commit();log_action($conn,'IMPORT_FAMILIES','import_batches',$batchId,"Completed family import batch; imported=$imported; skipped=$skipped");@unlink($state['path']);unset($_SESSION['family_import_preview']);header("Location: ../auth/families/import.php?completed=$batchId");}catch(Throwable $e){$conn->rollback();$stmt=$conn->prepare("UPDATE import_batches SET status='failed',validation_summary=?,completed_at=NOW() WHERE id=?");$safe=json_encode(['error'=>'Import transaction failed; no family rows committed.']);$stmt->bind_param('si',$safe,$batchId);$stmt->execute();error_log('Family import failed: '.$e->getMessage());header('Location: ../auth/families/import.php?error=import_failed');}
